import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const f=JSON.parse('{"title":"FR 3.7.16 — Create Collaborator Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/06-ai-features/3-7-16-create-collaborator-profile/spec.md","filePath":"feature/srs/06-ai-features/3-7-16-create-collaborator-profile/spec.md"}'),c={name:"feature/srs/06-ai-features/3-7-16-create-collaborator-profile/spec.md"};function d(i,e,l,n,s,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-7-16-—-create-collaborator-profile" tabindex="-1">FR 3.7.16 — Create Collaborator Profile <a class="header-anchor" href="#fr-3-7-16-—-create-collaborator-profile" aria-label="Permalink to &quot;FR 3.7.16 — Create Collaborator Profile&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.7.16</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-103</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Create Collaborator Profile</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">AI Features (<code>3.7</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20</code>, <code>BR-51</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01</code>, <code>MSG02</code>, <code>MSG03</code>, <code>MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Consolidates <code>partner-directory</code> DA-949)</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Allow authorized Agency leadership (<code>Owner</code> on Agency Directory <code>/api/v1/agencies/{agencyId}/collaborators</code>, and <code>Owner</code>/<code>Manager</code> via <code>/api/v1/collaborators</code> per workspace/agency policy) to onboard new third-party Collaborator &amp; Media Partner profiles (<code>KOL</code>, <code>KOC</code>, <code>NEWSPAPER</code>, <code>BANNER</code>, <code>TV</code>, <code>OTHER</code>) into <code>third_party_collaborators</code> with validated contact channels, rate-card metadata, <code>isActive = true</code>, <code>usageHistoryVerified = true</code>, and initial optimistic lock <code>version = 0</code> (<code>BR-51</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an <code>Owner</code> or <code>Manager</code>, I want to create a structured Collaborator Profile with partner category, niche/industry tags, pricing benchmarks, reach metrics, and validated phone/email/website contact details so that the partner is immediately available for AI recommendation (FR 3.7.19) and Campaign assignment.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Authorization &amp; Tenant Binding (<code>BR-20</code>):</strong> <code>agency_id</code> is bound strictly from the authenticated Agency context (<code>DirectoryPartnerController</code> / <code>CollaboratorController</code>), rejecting cross-Agency writes (<code>403 FORBIDDEN</code>, <code>MSG07</code>).</li><li><strong>Input &amp; Contact Validation (<code>BR-51</code>):</strong><ul><li><code>name</code>: Trimmed, required, <code>1..255</code> characters.</li><li><code>type</code>: Required enum (<code>KOL</code>, <code>KOC</code>, <code>NEWSPAPER</code>, <code>BANNER</code>, <code>TV</code>, <code>OTHER</code> — backed by <code>2026-11-16-collaborator-kol-type.sql</code>).</li><li><code>contactInfo</code> (JSONB object, <code>&lt;= 10,000</code> chars): Validates Vietnam &amp; international phone numbers (<code>7–15</code> digits, optional leading <code>+</code> and spaces/hyphens/parentheses), RFC-compliant email, and <code>http://</code> or <code>https://</code> website URLs on both UI and backend.</li><li><code>notes</code>: Optional, <code>&lt;= 10,000</code> characters. Unknown root payload fields or attempts to spoof <code>isActive</code>, <code>firstUsedAt</code>, <code>usageHistoryVerified</code>, or <code>version</code> are rejected (<code>400 BAD_REQUEST</code>, <code>MSG02</code>).</li></ul></li><li><strong>Lifecycle Initialization:</strong> Newly created rows persist with <code>is_active = true</code>, <code>first_used_at = NULL</code>, <code>usage_history_verified = true</code> (permitting clean hard-delete via FR 3.7.18 until first linked to a Campaign), and <code>version = 0</code>.</li><li><strong>Client Profile Quick-Fill Helper:</strong> <code>ClientProfileQuickFill.tsx</code> optionally assists pre-populating industry/audience alignment tags without mutating client records.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Form labels, type options, contact validation hints, and submit/cancel buttons use key-parallel <code>collaborators.form.*</code> and <code>collaborators.errors.*</code> in <code>vi.json</code> and <code>en.json</code>.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> <code>PartnerForm.tsx</code> and <code>PartnerContactFields.tsx</code> inputs, focus rings, error borders, and modal surfaces comply with semantic Light/Dark tokens.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Components:</strong> <code>pages/collaborators/components/PartnerForm.tsx</code>, <code>PartnerContactFields.tsx</code>, <code>ClientProfileQuickFill.tsx</code>.</li><li><strong>Mobile Screen:</strong> <code>src/screens/agency/AgencyCollaboratorsScreen.tsx</code> create modal.</li><li><strong>UI States:</strong><ul><li><strong>Initial / Auto-Focus:</strong> Dialog auto-focuses <code>name</code> input and closes cleanly on <code>Escape</code> (with unsaved-input guard if dirty).</li><li><strong>Submitting:</strong> Primary button shows loading spinner and disables duplicate clicks.</li><li><strong>Validation Error:</strong> Field-level inline error messages for invalid phone/email/URL or oversize notes.</li><li><strong>Success (<code>201 Created</code>):</strong> Closes modal, invalidates directory query cache, highlights newly created partner card, and shows localized toast.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth</th><th style="text-align:left;">Handler</th><th style="text-align:left;">Request / Response</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST /api/v1/agencies/{agencyId}/collaborators</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>DirectoryPartnerController.create()</code></td><td style="text-align:left;">Req: <code>CreateDirectoryPartnerRequest</code> -&gt; <code>201 ApiResponse&lt;DirectoryPartnerResponse&gt;</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/collaborators</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager</code>)</td><td style="text-align:left;"><code>CollaboratorController.create()</code></td><td style="text-align:left;">Req: <code>CreateCollaboratorRequest</code> -&gt; <code>201 ApiResponse&lt;CollaboratorResponse&gt;</code></td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>INVALID_CONTACT_FORMAT</code> (<code>400</code>, <code>MSG02</code>): Phone outside <code>7–15</code> digits, malformed email, or <code>javascript:</code> / non-HTTP(S) website scheme.</li><li><code>UNRECOGNIZED_FIELD</code> (<code>400</code>, <code>MSG02</code>): Payload attempts to override read-only lifecycle markers (<code>firstUsedAt</code>, <code>usageHistoryVerified</code>).</li><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): <code>Creator</code> or <code>Client</code> attempts to create an Agency directory partner.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Sibling SRS FRs:</strong> <a href="./../3-7-15-view-collaborator-directory/spec.html">FR 3.7.15 — View Collaborator Directory</a> · <a href="./../3-7-17-update-collaborator-profile/spec.html">FR 3.7.17 — Update Collaborator Profile</a> · <a href="./../3-7-18-remove-collaborator-profile/spec.html">FR 3.7.18 — Remove Collaborator Profile</a> · <a href="./../3-7-19-recommend-collaborator/spec.html">FR 3.7.19 — Recommend Collaborator</a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/06-ai-features.html">BA 3.7 AI Features</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified in <code>DirectoryPartnerControllerTest</code>, <code>DirectoryPartnerServiceTest</code>, <code>PartnerLifecycleMigrationTest</code>, Web Playwright form validation tests, <code>vi</code>/<code>en</code> i18n parity, and Light/Dark mode (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> External phone/email ownership verification via OTP for third-party KOL contacts (format validation only).</li></ul>',19)])])}const h=t(c,[["render",d]]);export{f as __pageData,h as default};
